use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

pub struct StatsCommand;

fn aggregate_by_project(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<(Option<i64>, String), i64>::new();

    for entry in entries {
        if entry.duration < 0 {
            continue;
        }

        let project = entry
            .project
            .as_ref()
            .map(|project| (Some(project.id), project.name.clone()))
            .unwrap_or_else(|| (None, "No Project".to_string()));
        *totals.entry(project).or_default() += entry.duration;
    }

    let mut totals: Vec<_> = totals
        .into_iter()
        .map(|((_, name), duration)| (name, duration))
        .collect();
    totals.sort_by(|(name_a, duration_a), (name_b, duration_b)| {
        duration_b.cmp(duration_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = if since.is_some() || until.is_some() {
            utilities::normalize_time_entry_list_filters(since, until)?
        } else {
            (None, None)
        };
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = aggregate_by_project(&entries);
        let total_seconds: i64 = totals.iter().map(|(_, duration)| duration).sum();

        for (project, duration) in totals {
            println!(
                "{}  {}",
                utilities::format_duration_compact(duration),
                project
            );
        }
        println!(
            "{}  Total",
            utilities::format_duration_compact(total_seconds)
        );

        Ok(())
    }
}

